import{_ as t,l as i,o as e,c as d,v as r,p as l,x as n,d as s,i as E,S as c}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"央行独立性简史","description":"","frontmatter":{"title":"央行独立性简史","date":"2026-09-10T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/cb-independence-history.md","filePath":"econ/cb-independence-history.md","lastUpdated":1789023840000}'),p={name:"econ/cb-independence-history.md"};function B(h,a,A,m,u,_){const o=i("Mermaid");return e(),d("div",null,[a[1]||(a[1]=r('<h1 id="央行独立性简史" tabindex="-1">央行独立性简史 <a class="header-anchor" href="#央行独立性简史" aria-label="Permalink to &quot;央行独立性简史&quot;">​</a></h1><div class="epigraph"><p>把利率交给一个难被解雇的机构，是为了堵住「选举前放水、事后通胀」的时间不一致；独立是政治委托，不是技术中性，最后贷款人与财政的边界会在危机里被重新谈判。</p><footer>—— Kydland and Prescott, JPE 1977；Barro and Gordon；Rogoff 保守央行；Alesina and Summers, JMCB 1993；Cukierman；Bernanke, The Courage to Act, 2015；Eichengreen</footer></div><p><a href="/econ/eurozone-debt-crisis">上一课</a>显示：没有明确的主权最后买家时，同盟内利差可以跳到坏均衡；OMT 一出，边界立刻变成「央行是否在财政化」。本课是经济史对照课的最后一课，也是本批领域课的收束。缺口不是列各国立法年份，而是：独立性怎样从金本位纪律、滞胀教训、2008 扩表、欧债承诺里长出来，又怎样在危机里被压薄。不承诺下一课程；读完本课，默认已能用委托与时间一致读央行，而不是用「独立永远正确」读。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Kydland–Prescott / Barro–Gordon：相机抉择下，承诺低通胀不可信，均衡通胀偏高。Rogoff：任命一位更厌恶通胀的保守银行家，降低偏误。金本位曾是金属版承诺，代价是大萧条那种通缩枷锁。1970 年代相机迁就给出滞胀。1980–90 年代新西兰、英国、欧元区把目标与工具写进法律：工具独立（选 \\(i\\)）与目标独立（选通胀目标）要分开。缺口是危机后的第三句：QE、购债、监管宏观审慎，使资产负债表重新贴上财政。Alesina–Summers 的跨国相关是描述，不是证明独立足够。</p><h3 id="独立不是央行永远正确" tabindex="-1">独立不是央行永远正确 <a class="header-anchor" href="#独立不是央行永远正确" aria-label="Permalink to &quot;独立不是央行永远正确&quot;">​</a></h3><p>独立降低通胀偏误，不保证金融稳定，也不保证最后贷款人落在社会最优。任命、目标定义、危机协调仍是政治。把独立读成「不受选举约束所以科学」，会漏掉委托链：议会把目标交给央行，危机时目标可能被改写。欧债课的 OMT 是委托被压到极限的例子：不做则坏均衡，做则被指财政化。</p><p><span class="marginnote">Cukierman 的独立性指数把法律条文量化，与通胀负相关。条文与实际独立可以分开：财政主导下，法律独立会被债务滚续吞掉。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照本课序的危机。(1) 金本位：纪律来自黄金，独立空间小，失败是通缩。(2) 布雷顿：中心承诺兑黄金，外围独立有限。(3) 滞胀：浮动后独立不足，失败是通胀。(4) 东亚：外围央行印不出美元。(5) 2008：中心央行必须扩到影子链，独立变成「能否做非常规」。 (6) 欧债：独立机构是否允许对主权做条件式承诺。工具：通胀目标、泰勒原则、沟通。财政：债务可持续课的 \\(r\\) 有一部分是央行定的；主导权在危机里会翻转。</p>',10)),(e(),l(c,null,{default:n(()=>[E(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20TIME%5B%22%E6%97%B6%E9%97%B4%E4%B8%8D%E4%B8%80%E8%87%B4%3A%20%E9%80%9A%E8%83%80%E5%81%8F%E8%AF%AF%22%5D%20--%3E%20METAL%5B%22%E9%87%91%E6%9C%AC%E4%BD%8D%E9%87%91%E5%B1%9E%E7%BA%AA%E5%BE%8B%22%5D%0A%20%20TIME%20--%3E%20LAW%5B%22%E6%B3%95%E5%BE%8B%E7%8B%AC%E7%AB%8B%E5%8A%A0%E9%80%9A%E8%83%80%E7%9B%AE%E6%A0%87%22%5D%0A%20%20LAW%20--%3E%20CRISIS%5B%22%E5%8D%B1%E6%9C%BA%3A%20%E6%9C%80%E5%90%8E%E8%B4%B7%E6%AC%BE%E4%BA%BA%E6%89%A9%E8%A1%A8%22%5D%0A%20%20CRISIS%20--%3E%20BORDER%5B%22%E4%B8%8E%E8%B4%A2%E6%94%BF%E7%9A%84%E8%BE%B9%E7%95%8C%E8%A2%AB%E9%87%8D%E8%B0%88%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>不要把独立性指数当政策充分统计。目标含糊（「增长与稳定」并列且权重随选举变）等于没有承诺。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是委托。社会要低通胀，又要危机时的弹性。把日常 \\(i\\) 交给难被解雇的机构，堵住政治周期；把目标写死，堵住 Barro–Gordon 的诱惑。金本位把弹性关死；滞胀证明弹性会被滥用；2008 证明弹性有时必须大到扩表。欧债证明弹性必须写到主权债市场上，否则多重均衡。独立不是「越远越好」，是在偏误与弹性之间选一个可验证的规则。财政主导：债太高时，央行被迫压 \\(r\\)，独立名存实亡——主权课的阈值虽然不是定律，主导权转移是真的。</p><p>与公共财政漏桶对照：独立降低的是一种政治弹性带来的通胀漏，不降低劳动税的激励漏。两套漏不要混。</p><p><span class="marginnote">Bernanke 的回忆录把 2008 写成在独立框架里做最后贷款人。争议仍在：何处止于 Bagehot、何处开始财政。史课停在机制，不给现任央行打分。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不预测下一次制度改写，不提供如何交易利率决议的步骤。经济史领域课到此结束，没有下一课。不要把本课读成「应当永远扩表」或「应当回到金本位」——两条都是用一种枷锁替代全部历史。后文（若读者离开本栏）默认：央行是被委托的规则机器；危机改变的是规则的边界，不是经济学不再适用。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>独立用来对付通胀的时间不一致，是委托不是神学。</li><li>金本位纪律过硬，滞胀证明过软，通胀目标是折中。</li><li>2008 与欧债把最后贷款人扩到影子链与主权，边界重开。</li><li>财政主导可以吞掉法律独立；指数不是充分统计。</li><li>本课是经济史对照的收束，不接下一课。</li><li>出处：Kydland and Prescott 1977；Barro and Gordon；Rogoff；Alesina and Summers 1993；Cukierman；Bernanke 2015；Eichengreen。</li></ul>',9))])}const b=t(p,[["render",B]]);export{T as __pageData,b as default};
